#!/usr/bin/env bash
# Resumable TinyStories pipeline: data, codec, generator, AR baseline, evaluation.
#
#   nohup scripts/run_text_pipeline.sh configs/tinystories-e21.json > runs/tinystories-e21-pipeline.log 2>&1 &
#
# Each stage is skipped when its exported result exists, resumed with --resume
# when its full training state exists, and started fresh otherwise. Rerunning
# the same command after an interruption therefore continues from the last
# full-state checkpoint (see docs/RECOVERY.md). Do not edit this file while a
# pipeline is running.
set -euo pipefail

config=${1:?usage: run_text_pipeline.sh CONFIG}
name=$(basename "$config" .json)
out=$(uv run python -c "import json,sys; print(json.load(open(sys.argv[1]))['out_dir'])" "$config")
export="$out/export"
mkdir -p runs

gpu() { ioreg -r -d 1 -c IOAccelerator | grep -o '"Device Utilization %"=[0-9]*' || true; }

stage() {
  local cmd=$1 state=$2 done_file=$3
  if [[ -f "$done_file" ]]; then
    echo "$(date '+%F %T') skip $cmd: $done_file exists"
    return
  fi
  local flag=()
  [[ -f "$state" ]] && flag=(--resume)
  echo "$(date '+%F %T') start $cmd ${flag[*]:-} ($(gpu))"
  uv run python -m ncm_mlx official "$cmd" --config "$config" ${flag[@]+"${flag[@]}"} 2>&1 | tee -a "runs/$name-$cmd.log"
  local status=${PIPESTATUS[0]}
  if [[ $status -ne 0 ]]; then
    echo "$(date '+%F %T') $cmd exited $status"
    exit "$status"
  fi
  echo "$(date '+%F %T') done $cmd ($(gpu))"
}

uv run python -m ncm_mlx official prepare-data --config "$config" > "runs/$name-prepare.log" 2>&1
stage train-codec "$out/codec-training.safetensors" "$export/codec.safetensors"
stage train-generator "$out/generator-training.safetensors" "$export/generator.safetensors"
stage train-ar "$out/ar-training.safetensors" "$export/ar.safetensors"
if [[ ! -f "runs/$name-eval/report.json" ]]; then
  echo "$(date '+%F %T') start eval-text ($(gpu))"
  uv run --group text-eval python -m ncm_mlx official eval-text --config "$config" 2>&1 | tee -a "runs/$name-eval.log"
  echo "$(date '+%F %T') done eval-text ($(gpu))"
fi
echo "$(date '+%F %T') pipeline complete"
